import React,{useEffect,useLayoutEffect,useMemo,useRef,useState} from 'react';
import{createRoot}from'react-dom/client';
import{BrowserRouter,Routes,Route,Link,NavLink,useNavigate,useLocation,Navigate}from'react-router-dom';
import{BookOpen,Brain,ChartNoAxesColumnIncreasing,ChevronDown,ChevronRight,Cloud,Compass,House,Menu,Search,ShieldCheck,Sparkles,Target,Users,Mail,ArrowLeft,CheckCircle2,Clock3,LogOut,BookMarked,CalendarDays,FileText,Download,Send,X,Eye,EyeOff,Sun,Moon,PanelLeftClose,PanelLeftOpen}from'lucide-react';
import'./style.css';
import'./portal.css';
import'./polish.css';
import'./dark.css';
const API='/api';
const reduceMotion=()=>typeof window!=='undefined'&&window.matchMedia('(prefers-reduced-motion: reduce)').matches;
const pageTitles={'/':'Home','/about':'About','/contact':'Contact','/resources':'Resources','/signin':'Sign in','/signup':'Create account','/quiz':'Practice quiz','/flashcards':'Flashcards','/planner':'Study planner','/progress':'Progress','/assistant':'Study assistant'};
/* Counts a number up once on mount. Writes straight to the DOM so it never re-renders per frame. */
function CountUp({to,suffix='',duration=900}){const ref=useRef(null);useEffect(()=>{const node=ref.current&&ref.current.firstChild;if(!node)return;if(reduceMotion()){node.nodeValue=to+suffix;return;}let raf,start;const tick=t=>{start??=t;const p=Math.min((t-start)/duration,1);node.nodeValue=Math.round(to*(1-Math.pow(1-p,3)))+suffix;if(p<1)raf=requestAnimationFrame(tick);};raf=requestAnimationFrame(tick);return()=>cancelAnimationFrame(raf);},[to,suffix,duration]);return <span className="countUp" ref={ref}>{to+suffix}</span>;}
/* Route-level motion: scroll reset, title, focus, scroll reveal, and pausing off-screen loops. */
function useMotion(pathname,ready,mobile,setMobile){
 useEffect(()=>{window.scrollTo(0,0);document.title=(pageTitles[pathname]?pageTitles[pathname]+' | ':'')+'CloudReady AZ 900 Study Coach';},[pathname]);
 useEffect(()=>{if(!mobile)return;const onKey=e=>{if(e.key==='Escape')setMobile(false);};window.addEventListener('keydown',onKey);return()=>window.removeEventListener('keydown',onKey);},[mobile,setMobile]);
 useLayoutEffect(()=>{
  if(!ready||reduceMotion()||typeof IntersectionObserver==='undefined')return;
  const targets=[...document.querySelectorAll('.stats,.progressCards,.toolCard,.topicCard,.contentCard,.principleGrid>div,.featureInner>*,.cta,.section>.sectionHead,.reportCard')];
  const io=new IntersectionObserver(entries=>{entries.forEach(en=>{if(!en.isIntersecting)return;const el=en.target;io.unobserve(el);el.classList.add('is-in');el.addEventListener('animationend',()=>el.classList.remove('reveal','is-in'),{once:true});});},{threshold:.12,rootMargin:'0px 0px -6% 0px'});
  targets.forEach(el=>{const i=el.parentElement?Array.prototype.indexOf.call(el.parentElement.children,el):0;el.style.setProperty('--i',Math.min(i,5));el.classList.add('reveal');io.observe(el);});
  const hero=document.querySelector('.heroVisual');let heroIo;
  if(hero){heroIo=new IntersectionObserver(([en])=>hero.classList.toggle('is-paused',!en.isIntersecting));heroIo.observe(hero);}
  return()=>{io.disconnect();if(heroIo)heroIo.disconnect();targets.forEach(el=>el.classList.remove('reveal','is-in'));};
 },[pathname,ready]);
}
/* Theme: one source of truth on <html data-theme>. Everything else (toggle, palette) calls applyTheme. */
function applyTheme(next,persist=true){const apply=()=>{document.documentElement.dataset.theme=next;const m=document.querySelector('meta[name="theme-color"]');if(m)m.setAttribute('content',next==='dark'?'#0f1020':'#5145e5');window.dispatchEvent(new CustomEvent('cr-theme',{detail:next}));};if(persist){try{localStorage.setItem('cr_theme',next);}catch{}}if(document.startViewTransition&&!reduceMotion())document.startViewTransition(apply);else apply();}
const currentTheme=()=>document.documentElement.dataset.theme==='dark'?'dark':'light';
function useTheme(){const[theme,setTheme]=useState(currentTheme);useEffect(()=>{const onTheme=e=>setTheme(e.detail==='dark'?'dark':'light');const mq=window.matchMedia('(prefers-color-scheme: dark)');const onSystem=e=>{let stored=null;try{stored=localStorage.getItem('cr_theme');}catch{}if(!stored)applyTheme(e.matches?'dark':'light',false);};window.addEventListener('cr-theme',onTheme);mq.addEventListener('change',onSystem);return()=>{window.removeEventListener('cr-theme',onTheme);mq.removeEventListener('change',onSystem);};},[]);return theme;}
function ThemeToggle(){const theme=useTheme(),dark=theme==='dark';return <button type="button" className="themeToggle" onClick={()=>applyTheme(dark?'light':'dark')} aria-pressed={dark} aria-label={dark?'Switch to light theme':'Switch to dark theme'} title={dark?'Light theme':'Dark theme'}><Sun className="iconSun" size={18} aria-hidden="true"/><Moon className="iconMoon" size={18} aria-hidden="true"/></button>;}
const isMac=typeof navigator!=='undefined'&&/Mac|iPhone|iPad/.test(navigator.platform||'');
function PaletteBtn({onOpen,className=''}){return <button type="button" className={('paletteBtn '+className).trim()} onClick={onOpen} aria-label="Open command palette" aria-keyshortcuts="Control+K Meta+K" title="Search and commands"><Search size={17} aria-hidden="true"/><span className="paletteText">Search</span><kbd aria-hidden="true">{isMac?'⌘ K':'Ctrl K'}</kbd></button>;}
/* Command palette: Ctrl/Cmd+K. Combobox + listbox pattern, arrow keys, Enter, Esc, focus returns to the opener. */
function CommandPalette({open,commands,onClose}){
 const[query,setQuery]=useState(''),[active,setActive]=useState(0),[closing,setClosing]=useState(false),inputRef=useRef(null),listRef=useRef(null),opener=useRef(null);
 const results=useMemo(()=>{const q=query.trim().toLowerCase();return commands.filter(c=>!q||(c.label+' '+(c.keywords||'')+' '+c.group).toLowerCase().includes(q));},[query,commands]);
 useEffect(()=>{if(open){opener.current=document.activeElement;setQuery('');setActive(0);setClosing(false);const id=requestAnimationFrame(()=>inputRef.current&&inputRef.current.focus());return()=>cancelAnimationFrame(id);}else if(opener.current){const el=opener.current;opener.current=null;if(el&&el.focus&&document.contains(el))el.focus({preventScroll:true});}},[open]);
 useEffect(()=>{setActive(0);},[query]);
 useEffect(()=>{if(!open)return;const el=listRef.current&&listRef.current.querySelector('[aria-selected="true"]');if(el)el.scrollIntoView({block:'nearest'});},[active,open]);
 useEffect(()=>{if(!open)return;const prev=document.body.style.overflow;document.body.style.overflow='hidden';return()=>{document.body.style.overflow=prev;};},[open]);
 if(!open)return null;
 const dismiss=()=>{if(reduceMotion()){onClose();return;}setClosing(true);setTimeout(()=>{setClosing(false);onClose();},140);};
 const run=cmd=>{if(!cmd)return;onClose();setTimeout(()=>cmd.run(),0);};
 const onKeyDown=e=>{
  if(e.key==='Escape'){e.preventDefault();dismiss();}
  else if(e.key==='ArrowDown'){e.preventDefault();if(results.length)setActive(a=>(a+1)%results.length);}
  else if(e.key==='ArrowUp'){e.preventDefault();if(results.length)setActive(a=>(a-1+results.length)%results.length);}
  else if(e.key==='Home'){e.preventDefault();setActive(0);}
  else if(e.key==='End'){e.preventDefault();setActive(Math.max(results.length-1,0));}
  else if(e.key==='Enter'){e.preventDefault();run(results[active]);}
  else if(e.key==='Tab'){e.preventDefault();}
 };
 let lastGroup='';
 return <div className={closing?'cmdBackdrop closing':'cmdBackdrop'} onMouseDown={e=>{if(e.target===e.currentTarget)dismiss();}}>
  <div className="cmdPanel" role="dialog" aria-modal="true" aria-label="Command palette" onKeyDown={onKeyDown}>
   <div className="cmdInputRow"><Search size={19} aria-hidden="true"/><input ref={inputRef} role="combobox" aria-expanded="true" aria-controls="cmd-list" aria-activedescendant={results[active]?'cmd-opt-'+results[active].id:undefined} aria-autocomplete="list" autoComplete="off" spellCheck="false" value={query} onChange={e=>setQuery(e.target.value)} placeholder="Search pages and actions..."/><span className="cmdEsc" aria-hidden="true">Esc</span></div>
   <ul className="cmdList" id="cmd-list" role="listbox" aria-label="Commands" ref={listRef}>
    {results.map((c,n)=>{const head=c.group!==lastGroup;lastGroup=c.group;const Icon=c.icon;return <React.Fragment key={c.id}>{head&&<li className="cmdGroup" role="presentation">{c.group}</li>}<li id={'cmd-opt-'+c.id} role="option" aria-selected={n===active} className="cmdItem" onMouseMove={()=>{if(n!==active)setActive(n);}} onClick={()=>run(c)}><span className="cmdIcon"><Icon size={17} aria-hidden="true"/></span><span>{c.label}</span>{c.meta&&<span className="cmdMeta">{c.meta}</span>}</li></React.Fragment>;})}
   </ul>
   {!results.length&&<div className="cmdEmpty" role="status">No commands match "{query}".</div>}
   <div className="cmdHints" aria-hidden="true"><span><kbd>↑</kbd><kbd>↓</kbd> navigate</span><span><kbd>↵</kbd> select</span><span><kbd>Esc</kbd> close</span></div>
  </div>
 </div>;
}
function NavDrop({closeMenu}){const[open,setOpen]=useState(false),ref=useRef(null);useEffect(()=>{if(!open)return;const onDown=e=>{if(ref.current&&!ref.current.contains(e.target))setOpen(false);},onKey=e=>{if(e.key==='Escape')setOpen(false);};document.addEventListener('pointerdown',onDown);document.addEventListener('keydown',onKey);return()=>{document.removeEventListener('pointerdown',onDown);document.removeEventListener('keydown',onKey);};},[open]);const go=()=>{setOpen(false);closeMenu();};return <div className={open?'navDrop open':'navDrop'} ref={ref}><button type="button" aria-expanded={open} aria-controls="study-tools-menu" onClick={()=>setOpen(!open)}>Study tools <ChevronDown size={15} aria-hidden="true"/></button><div className="dropMenu" id="study-tools-menu"><Link to="/quiz" onClick={go}>Practice quiz</Link><Link to="/flashcards" onClick={go}>Flashcards</Link><Link to="/planner" onClick={go}>Study planner</Link><Link to="/progress" onClick={go}>Progress report</Link><Link to="/assistant" onClick={go}>Study assistant</Link></div></div>;}
const questions=[
{topic:'Cloud concepts',q:'A company wants to use computing resources without buying physical servers. Which cloud benefit best describes this?',opts:['High availability','Capital expenditure reduction','Manual scaling','Local redundancy'],answer:1,why:'Cloud services can reduce upfront capital spending because the provider owns and maintains the underlying infrastructure.'},
{topic:'Cloud concepts',q:'Which cloud model combines a private environment with public cloud services?',opts:['Public cloud','Private cloud','Hybrid cloud','Community network'],answer:2,why:'A hybrid cloud connects private infrastructure with public cloud services so workloads and data can be used across both.'},
{topic:'Architecture and services',q:'Which Azure service is designed to host a web application without managing the underlying servers?',opts:['Azure App Service','Azure Policy','Azure Files','Azure Monitor'],answer:0,why:'Azure App Service is a managed platform for hosting web applications and APIs.'},
{topic:'Management and governance',q:'A team needs to apply consistent rules to resources across subscriptions. Which service should they consider?',opts:['Azure DNS','Azure Policy','Azure Virtual Network','Azure Bastion'],answer:1,why:'Azure Policy helps assess and enforce organizational standards for resources.'},
{topic:'Security and identity',q:'What is the principle of granting only the permissions needed for a task called?',opts:['Elasticity','Least privilege','High availability','Geo replication'],answer:1,why:'Least privilege reduces risk by giving a person or service only the access required for its work.'},
{topic:'Management and governance',q:'Which tool helps estimate expected Azure costs before deploying resources?',opts:['Azure Pricing Calculator','Azure Service Health','Microsoft Entra ID','Azure Advisor only'],answer:0,why:'The Azure Pricing Calculator helps estimate costs for planned services and configurations.'}
];
const topics=[['Cloud concepts',78],['Architecture and services',64],['Security and identity',52],['Management and governance',43]];
const portalPaths=new Set(['/quiz','/flashcards','/planner','/progress','/assistant']);
function RequireAuth({user,children}){const location=useLocation();return user?children:<Navigate to="/signin" replace state={{from:location.pathname+location.search}}/>;}
function App(){
 const[mobile,setMobile]=useState(false),[user,setUser]=useState(null),[authChecking,setAuthChecking]=useState(()=>Boolean(localStorage.getItem('cr_token'))),[sessionError,setSessionError]=useState('');
 const loc=useLocation(),navigate=useNavigate(),isAuthPage=loc.pathname==='/signin'||loc.pathname==='/signup',isPortal=Boolean(user)&&portalPaths.has(loc.pathname);
 useMotion(loc.pathname,!authChecking,mobile,setMobile);
 useEffect(()=>{const token=localStorage.getItem('cr_token');if(!token){localStorage.removeItem('cr_user');setAuthChecking(false);return;}let active=true;fetch(`${API}/me`,{headers:{Authorization:`Bearer ${token}`}}).then(async res=>{const data=await res.json();if(!res.ok){if(res.status===401||res.status===404){localStorage.removeItem('cr_token');localStorage.removeItem('cr_user');return;}throw new Error(data.error||'Could not verify your session.');}if(!data.user||typeof data.user.name!=='string')throw new Error('The server returned an invalid account profile.');localStorage.setItem('cr_user',JSON.stringify(data.user));if(active)setUser(data.user);}).catch(err=>{if(active)setSessionError(err.message||'Could not verify your session. Please try again.');}).finally(()=>{if(active)setAuthChecking(false);});return()=>{active=false;};},[]);
 const closeMenu=()=>setMobile(false);
 const logout=()=>{localStorage.removeItem('cr_token');localStorage.removeItem('cr_user');setUser(null);setSessionError('');closeMenu();navigate('/',{replace:true});};
 const acceptAuth=nextUser=>{localStorage.setItem('cr_user',JSON.stringify(nextUser));setUser(nextUser);setSessionError('');};
 const theme=useTheme(),[palette,setPalette]=useState(false),[pinned,setPinned]=useState(()=>{try{return localStorage.getItem('cr_sidebar_pinned')==='1';}catch{return false;}});
 const togglePin=()=>setPinned(p=>{const next=!p;try{localStorage.setItem('cr_sidebar_pinned',next?'1':'0');}catch{}return next;});
 useEffect(()=>{const onKey=e=>{const typing=/INPUT|TEXTAREA|SELECT/.test((e.target&&e.target.tagName)||'')||(e.target&&e.target.isContentEditable);if((e.metaKey||e.ctrlKey)&&e.key.toLowerCase()==='k'){e.preventDefault();setPalette(o=>!o);}else if(e.key==='/'&&!typing&&!e.metaKey&&!e.ctrlKey&&!e.altKey){e.preventDefault();setPalette(true);}};window.addEventListener('keydown',onKey);return()=>window.removeEventListener('keydown',onKey);},[]);
 const commands=useMemo(()=>{const go=to=>()=>navigate(to),gate=user?'':'Sign in';const list=[{id:'home',label:'Home',group:'Go to',icon:House,run:go('/')},{id:'quiz',label:'Practice quiz',group:'Go to',icon:BookOpen,meta:gate,keywords:'questions test exam az-900',run:go('/quiz')},{id:'flashcards',label:'Flashcards',group:'Go to',icon:BookMarked,meta:gate,keywords:'cards revise recall',run:go('/flashcards')},{id:'planner',label:'Study planner',group:'Go to',icon:CalendarDays,meta:gate,keywords:'schedule plan date',run:go('/planner')},{id:'progress',label:'Progress overview',group:'Go to',icon:Target,meta:gate,keywords:'report results history',run:go('/progress')},{id:'assistant',label:'Study assistant',group:'Go to',icon:Sparkles,meta:gate,keywords:'ai summary research',run:go('/assistant')},{id:'resources',label:'Resources',group:'Go to',icon:FileText,keywords:'library notes topics',run:go('/resources')},{id:'about',label:'About CloudReady',group:'Go to',icon:Compass,run:go('/about')},{id:'contact',label:'Contact and feedback',group:'Go to',icon:Mail,run:go('/contact')},{id:'theme',label:theme==='dark'?'Switch to light theme':'Switch to dark theme',group:'Actions',icon:theme==='dark'?Sun:Moon,keywords:'dark light appearance mode',run:()=>applyTheme(theme==='dark'?'light':'dark')}];if(isPortal)list.push({id:'pin',label:pinned?'Unpin sidebar (hide until hover)':'Pin sidebar open',group:'Actions',icon:pinned?PanelLeftClose:PanelLeftOpen,keywords:'sidebar menu collapse rail',run:togglePin});if(user)list.push({id:'signout',label:'Sign out',group:'Account',icon:LogOut,run:logout});else list.push({id:'signin',label:'Sign in',group:'Account',icon:Users,run:go('/signin')},{id:'signup',label:'Create account',group:'Account',icon:Users,run:go('/signup')});return list;},[user,theme,isPortal,pinned]);
 if(authChecking)return <div className="sessionChecking" role="status"><span className="spinner" aria-hidden="true"/> Checking your session…</div>;
 return <div className={(isAuthPage?'app authRoute':'app')+(pinned?' sidebarPinned':'')}>
  <a className="skipLink" href="#main">Skip to main content</a>
  {isAuthPage?<header className="topbar authTopbar"><Link to="/" className="brand"><span className="brandmark"><Cloud size={23}/></span><span>CloudReady<small>AZ 900 Study Coach</small></span></Link><Link to="/" className="authHome"><ArrowLeft size={16}/> Back home</Link><ThemeToggle/></header>:isPortal?
   <header className="topbar portalTopbar">{mobile&&<button className="portalBackdrop" aria-label="Close learner navigation" onClick={closeMenu}/>}<button className="mobileMenu" onClick={()=>setMobile(!mobile)} aria-label="Toggle portal navigation" aria-expanded={mobile}><Menu/></button><span className="portalHeaderTitle">Learner portal</span><nav aria-label="Learner portal" className={mobile?'nav portalNav open':'nav portalNav'}><Link to="/progress" className="portalBrand" onClick={closeMenu}><span className="brandmark"><Cloud size={23}/></span><span>CloudReady<small>LEARNER PORTAL</small></span></Link><span className="portalNavLabel">YOUR LEARNING</span><NavLink to="/progress" onClick={closeMenu}><House size={18}/><span className="navLabel">Overview</span></NavLink><NavLink to="/quiz" onClick={closeMenu}><BookOpen size={18}/><span className="navLabel">Practice</span></NavLink><NavLink to="/flashcards" onClick={closeMenu}><BookMarked size={18}/><span className="navLabel">Flashcards</span></NavLink><NavLink to="/planner" onClick={closeMenu}><CalendarDays size={18}/><span className="navLabel">Planner</span></NavLink><NavLink to="/assistant" onClick={closeMenu}><Sparkles size={18}/><span className="navLabel">Assistant</span></NavLink><NavLink to="/resources" onClick={closeMenu}><Compass size={18}/><span className="navLabel">Resources</span></NavLink><div className="portalNavFooter"><ShieldCheck size={17}/><span>Keep learning at your pace.</span><button type="button" className="pinBtn" onClick={togglePin} aria-pressed={pinned} aria-label={pinned?'Unpin sidebar so it hides until hover':'Pin sidebar open'} title={pinned?'Unpin sidebar':'Pin sidebar open'}>{pinned?<PanelLeftClose size={17} aria-hidden="true"/>:<PanelLeftOpen size={17} aria-hidden="true"/>}</button></div><div className="mobileUserActions"><span className="userPillMobile">{user.name||'Learner'}</span><button className="btn secondary small" onClick={logout}>Sign out</button></div></nav><div className="topActions"><PaletteBtn onOpen={()=>setPalette(true)}/><ThemeToggle/><span className="userPill">{user.name||'Learner'}</span><button className="iconBtn" onClick={logout} title="Sign out" aria-label="Sign out"><LogOut size={17}/></button></div></header>:
   <header className="topbar"><Link to="/" className="brand"><span className="brandmark"><Cloud size={23}/></span><span>CloudReady<small>AZ 900 Study Coach</small></span></Link><button className="mobileMenu" onClick={()=>setMobile(!mobile)} aria-label="Toggle menu" aria-expanded={mobile}><Menu aria-hidden="true"/></button><nav aria-label="Main navigation" className={mobile?'nav open':'nav'}><NavLink to="/" end onClick={closeMenu}>Home</NavLink><NavLink to="/about" onClick={closeMenu}>About</NavLink><NavDrop closeMenu={closeMenu}/><NavLink to="/resources" onClick={closeMenu}>Resources</NavLink><NavLink to="/contact" onClick={closeMenu}>Contact</NavLink>{user&&<div className="mobileUserActions"><span className="userPillMobile">{user.name||'Learner'}</span><button className="btn secondary small" onClick={logout}>Sign out</button></div>}<PaletteBtn className="navPalette" onOpen={()=>{closeMenu();setPalette(true);}}/></nav><div className="topActions"><PaletteBtn onOpen={()=>setPalette(true)}/><ThemeToggle/>{user?<><Link className="btn primary small" to="/progress">My portal</Link><button className="iconBtn" onClick={logout} title="Sign out" aria-label="Sign out"><LogOut size={17}/></button></>:<><Link className="signin" to="/signin">Sign in</Link><Link className="btn primary small" to="/signup">Create account</Link></>}</div></header>}
  <main id="main" tabIndex={-1} className={isPortal?'portalMain':''}>{sessionError&&<div className="sessionError" role="alert">{sessionError} Sign in again after the service is available.</div>}<div key={loc.pathname} className={loc.pathname==='/'?'':'pageEnter'}><Routes location={loc}><Route path="/" element={<Home user={user}/>}/><Route path="/about" element={<About/>}/><Route path="/contact" element={<Contact/>}/><Route path="/resources" element={<Resources/>}/><Route path="/signin" element={user?<Navigate to="/progress" replace/>:<Auth mode="signin" onAuth={acceptAuth}/>}/><Route path="/signup" element={user?<Navigate to="/progress" replace/>:<Auth mode="signup" onAuth={acceptAuth}/>}/><Route path="/quiz" element={<RequireAuth user={user}><Quiz/></RequireAuth>}/><Route path="/flashcards" element={<RequireAuth user={user}><Flashcards/></RequireAuth>}/><Route path="/planner" element={<RequireAuth user={user}><Planner/></RequireAuth>}/><Route path="/progress" element={<RequireAuth user={user}><Progress/></RequireAuth>}/><Route path="/assistant" element={<RequireAuth user={user}><Assistant/></RequireAuth>}/><Route path="*" element={<NotFound/>}/></Routes></div></main>
  {!isAuthPage&&!isPortal&&<footer><div className="footerInner"><Link to="/" className="brand footerBrand"><span className="brandmark"><Cloud size={20}/></span><span>CloudReady<small>Independent learning for cloud beginners</small></span></Link><p>Unofficial learning resource. Not affiliated with Microsoft.</p><div className="footerLinks"><Link to="/about">About</Link><Link to="/resources">Resources</Link><Link to="/contact">Contact</Link></div></div></footer>}
  <CommandPalette open={palette} commands={commands} onClose={()=>setPalette(false)}/>
 </div>;
}
function Home({user}){return <><section className="hero wrap"><div className="heroText"><div className="eyebrow"><span/> YOUR CLOUD LEARNING JOURNEY</div><h1>Build cloud confidence,<br/><em>one concept at a time.</em></h1><p>Practice the fundamentals, understand your mistakes, and create a study routine that works for you.</p><div className="heroBtns"><Link to="/quiz" className="btn primary">Start a practice quiz <ChevronRight size={18}/></Link><Link to="/about" className="btn secondary">Explore CloudReady</Link></div><div className="heroTrust"><div className="avatars"><span>J</span><span>A</span><span>M</span></div><span>Made for curious cloud learners</span></div></div><div className="heroVisual"><div className="orb orbOne"/><div className="orb orbTwo"/><div className="cloudPanel"><div className="panelHead"><span className="miniIcon"><Cloud/></span><span>Learning overview</span><span className="liveDot"/></div><div className="scoreCircle"><strong><CountUp to={72} suffix="%"/></strong><span>Practice progress</span></div><div className="miniBars">{topics.slice(0,3).map(([t,v])=><div key={t}><div><span>{t}</span><b>{v}%</b></div><span className="bar"><i style={{width:v+'%'}}/></span></div>)}</div><div className="panelFoot"><CheckCircle2 size={16}/> Keep building your knowledge</div></div><div className="floatingCard"><span className="floatIcon"><Brain size={20}/></span><span><b>Learn with purpose</b><small>Short practice sessions</small></span></div></div></section><section className="stats wrap"><Stat icon={<BookOpen/>} number="Original" label="Practice questions"/><Stat icon={<Target/>} number="4 areas" label="Focused learning topics"/><Stat icon={<ChartNoAxesColumnIncreasing/>} number="Your pace" label="Progress you can review"/><Stat icon={<ShieldCheck/>} number="Private" label="Your study history"/></section><section className="section wrap"><div className="sectionHead"><div><div className="eyebrow">YOUR LEARNING TOOLKIT</div><h2>Everything you need to keep moving</h2><p>Simple tools designed to make each study session count.</p></div><Link className="textLink" to="/resources">Browse resources <ChevronRight size={16}/></Link></div><div className="toolGrid"><ToolCard icon={<BookOpen/>} title="Practice quiz" desc="Test your understanding with original questions and clear explanations." to="/quiz" action="Take a quiz"/><ToolCard icon={<Brain/>} title="Flashcards" desc="Review important terms and strengthen recall in short sessions." to="/flashcards" action="Review cards"/><ToolCard icon={<CalendarDays/>} title="Study planner" desc="Build a realistic routine around your exam date and available time." to="/planner" action="Plan my study"/><ToolCard icon={<Sparkles/>} title="Study assistant" desc="Summarize notes or explore cloud topics without leaving the platform." to="/assistant" action="Open assistant"/></div></section><section className="featureBand"><div className="wrap featureInner"><div><div className="eyebrow">LEARN WITH CLARITY</div><h2>Understand the why,<br/><em>not just the answer.</em></h2><p>Every practice question includes an explanation that connects cloud terminology to real decisions and everyday scenarios.</p><Link to="/quiz" className="btn whiteBtn">Try a sample quiz <ChevronRight size={17}/></Link></div><div className="featureQuote"><span className="quoteMark">“</span><p>Good preparation is not about memorizing every term. It is about understanding what a service does and when it makes sense.</p><span className="quoteLine"/></div></div></section><section className="section wrap"><div className="sectionHead"><div><div className="eyebrow">A CLEAR STARTING POINT</div><h2>Learn the core areas</h2><p>Start with the fundamentals and build confidence topic by topic.</p></div></div><div className="topicGrid">{topics.map(([name,val],i)=><Link to="/quiz" className="topicCard" key={name}><span className={'topicIcon ti'+i}>{[<Cloud/>,<Compass/>,<ShieldCheck/>,<ChartNoAxesColumnIncreasing/>][i]}</span><h3>{name}</h3><p>{['Cloud models, benefits, and service types','Regions, services, and common architectures','Identity, access, and security foundations','Costs, governance, and resource management'][i]}</p><span className="topicBottom">Explore topic <ChevronRight size={16}/></span></Link>)}</div></section><section className="cta wrap"><div className="ctaIcon"><Users size={28}/></div><div><h2>Make your next study session count.</h2><p>Create a free account to keep your practice history and study plan in one place.</p></div><Link to={user?'/progress':'/signup'} className="btn primary">{user?'View my progress':'Create free account'} <ChevronRight size={18}/></Link></section></>}
function Stat({icon,number,label}){return <div className="stat"><span>{icon}</span><div><b>{number}</b><small>{label}</small></div></div>}
function ToolCard({icon,title,desc,to,action}){return <article className="toolCard"><span className="toolIcon">{icon}</span><h3>{title}</h3><p>{desc}</p><Link to={to}>{action} <ChevronRight size={16}/></Link></article>}
function PageHero({eyebrow,title,desc}){return <section className="pageHero wrap"><div className="eyebrow">{eyebrow}</div><h1>{title}</h1><p>{desc}</p></section>}
async function readApiResponse(response){const text=await response.text();if(!text.trim())throw new Error('The server returned an empty response. Check that the API server is running, then try again.');let data;try{data=JSON.parse(text);}catch{throw new Error('The server returned an unexpected response. Check that the API server is running, then try again.');}if(!response.ok)throw new Error(data.error||'The request could not be completed.');return data;}
function About(){return <><PageHero eyebrow="ABOUT CLOUDREADY" title={<>A clearer way to learn<br/><em>cloud fundamentals.</em></>} desc="CloudReady is an independent learning companion built to make cloud concepts easier to practise, understand, and remember."/><section className="contentGrid wrap"><article className="contentCard"><span className="largeIcon"><Compass/></span><h2>Built around understanding</h2><p>CloudReady uses original practice questions, plain language explanations, revision cards, and study planning to support consistent learning. It is designed for learners who want to understand the ideas behind cloud services rather than only memorize definitions.</p></article><article className="contentCard"><span className="largeIcon"><ShieldCheck/></span><h2>Independent and transparent</h2><p>This is an unofficial learning resource. It is not affiliated with Microsoft and does not provide official exam questions or guarantee exam results. Use it alongside current official learning materials.</p></article></section><section className="section wrap"><h2>Our learning principles</h2><div className="principleGrid"><div><b>01</b><h3>Practise actively</h3><p>Recall information and apply it to a situation.</p></div><div><b>02</b><h3>Learn from mistakes</h3><p>Use explanations to correct misunderstandings.</p></div><div><b>03</b><h3>Stay consistent</h3><p>Small regular sessions build stronger habits.</p></div></div></section></>}
function Contact(){const[done,setDone]=useState(false),[error,setError]=useState('');return <><PageHero eyebrow="CONTACT" title={<>We would like to<br/><em>hear from you.</em></>} desc="Share a question, report an issue, or suggest a learning feature."/><section className="contactGrid wrap"><div className="contactInfo"><span className="largeIcon"><Mail/></span><h2>Help us improve learning</h2><p>Use the form to share feedback about the study tools or content. Please do not include passwords or sensitive personal information.</p><div className="contactNote"><Clock3 size={18}/><span>Feedback is saved for this demo session only.</span></div></div><form className="formCard" onSubmit={async e=>{e.preventDefault();setError('');const f=e.currentTarget;const payload={name:f.elements[0].value,email:f.elements[1].value,category:f.elements[2].value,message:f.elements[3].value};try{const r=await fetch(`${API}/feedback`,{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(payload)});const d=await r.json();if(!r.ok)throw new Error(d.error||'Could not send feedback');setDone(true)}catch(err){setError(err.message+' Make sure the API server is running.')}}}>{done?<div className="successState"><CheckCircle2 size={36}/><h2>Thank you for your feedback</h2><p>Your message has been recorded in this demo view.</p><button className="btn secondary" type="button" onClick={()=>setDone(false)}>Send another message</button></div>:<>{error&&<div className="errorBox">{error}</div>}<label>Your name<input required placeholder="Enter your name"/></label><label>Email address<input required type="email" placeholder="you@example.com"/></label><label>What is this about?<select><option>General feedback</option><option>Question content</option><option>Technical issue</option><option>Feature suggestion</option></select></label><label>Your message<textarea required rows="5" placeholder="Tell us how we can improve CloudReady"/></label><button className="btn primary" type="submit">Send feedback <ChevronRight size={17}/></button></>}</form></section></>}
function Resources(){const[search,setSearch]=useState('');const resources=[['Cloud service models','Compare infrastructure, platform, and software services.','Cloud concepts'],['Shared responsibility','Understand how duties are divided between provider and customer.','Security and identity'],['Regions and availability zones','Learn how geographic infrastructure supports resilience.','Architecture and services'],['Identity and access','Explore authentication, authorization, and least privilege.','Security and identity'],['Cost management','Review budgets, pricing estimates, and governance controls.','Management and governance'],['Resource organization','Understand subscriptions, resource groups, and management groups.','Management and governance']];const filtered=resources.filter(r=>r.join(' ').toLowerCase().includes(search.toLowerCase()));return <><PageHero eyebrow="LEARNING LIBRARY" title={<>Useful resources for<br/><em>your next study session.</em></>} desc="Explore concise notes and original learning material organized around core cloud concepts."/><section className="wrap library"><div className="searchBox"><Search size={18}/><input type="search" aria-label="Search concepts and topics" value={search} onChange={e=>setSearch(e.target.value)} placeholder="Search concepts and topics"/></div><div className="resourceGrid">{filtered.map((r,i)=><article className="resourceCard" key={r[0]} style={{'--i':i}}><span className="resourceIcon"><FileText/></span><small>{r[2]}</small><h3>{r[0]}</h3><p>{r[1]}</p><Link to="/assistant" state={{topic:r[0]}}>Explore with study assistant <ChevronRight size={15}/></Link></article>)}</div>{!filtered.length&&<p className="emptyState" role="status">No resources match your search.</p>}</section></>}
function Auth({mode,onAuth}){const nav=useNavigate(),loc=useLocation(),[name,setName]=useState(''),[email,setEmail]=useState(''),[password,setPassword]=useState(''),[error,setError]=useState(''),[busy,setBusy]=useState(false),[showPw,setShowPw]=useState(false);const signup=mode==='signup';async function submit(e){e.preventDefault();setError('');setBusy(true);try{const res=await fetch(`${API}/auth/${signup?'signup':'signin'}`,{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({name,email,password})});const data=await readApiResponse(res);if(typeof data.token!=='string'||!data.token||!data.user||typeof data.user.name!=='string')throw new Error('The server response was incomplete. Please try again.');localStorage.setItem('cr_token',data.token);localStorage.setItem('cr_user',JSON.stringify(data.user));onAuth(data.user);const destination=typeof loc.state?.from==='string'&&loc.state.from.startsWith('/')&&!loc.state.from.startsWith('//')?loc.state.from:'/progress';nav(destination,{replace:true});}catch(err){setError(err instanceof Error?err.message:'Unable to complete your request. Check that the API server is running and try again.');}finally{setBusy(false)}}return <section className="authWrap"><div className="authCard"><aside className="authAside"><Link to="/" className="authAsideBrand"><span className="brandmark"><Cloud size={22}/></span><span>CloudReady<small>AZ 900 STUDY COACH</small></span></Link><div className="authAsideCopy"><div className="authAsideEyebrow"><Sparkles size={15}/> MADE FOR YOUR NEXT STEP</div><h2>Build confidence,<br/>one concept at a time.</h2><p>A focused space to practice, understand, and keep your cloud learning on track.</p></div><img className="authIllustration lightOnly" src="/cloudready-learning.svg" alt="CloudReady learning dashboard illustration"/><img className="authIllustration darkOnly" src="/cloudready-learning-dark.svg" alt="" aria-hidden="true"/><div className="authAsideFoot"><ShieldCheck size={17}/><span>Your learning space, thoughtfully organized.</span></div></aside><div className="authFormPanel"><div className="authFormHead"><span className="authKicker">{signup?'GET STARTED':'YOUR LEARNING SPACE'}</span><h1>{signup?'Create your account':'Welcome back'}</h1><p>{signup?'Save your progress and build a study routine.':'Sign in to continue your learning journey.'}</p></div><form className="authForm" onSubmit={submit}>{signup&&<label><span>Full name</span><span className="authInputWrap"><Users size={17} aria-hidden="true"/><input required minLength="2" autoComplete="name" value={name} onChange={e=>setName(e.target.value)} placeholder="Your name"/></span></label>}<label><span>Email address</span><span className="authInputWrap"><Mail size={17} aria-hidden="true"/><input required type="email" autoComplete="email" value={email} onChange={e=>setEmail(e.target.value)} placeholder="you@example.com"/></span></label><label><span>Password</span><span className="authInputWrap"><ShieldCheck size={17} aria-hidden="true"/><input required minLength={8} maxLength={128} type={showPw?'text':'password'} autoComplete={signup?'new-password':'current-password'} value={password} onChange={e=>setPassword(e.target.value)} placeholder="At least 8 characters"/><button type="button" className="pwToggle" onClick={()=>setShowPw(!showPw)} aria-label={showPw?'Hide password':'Show password'} aria-pressed={showPw}>{showPw?<EyeOff size={17} aria-hidden="true"/>:<Eye size={17} aria-hidden="true"/>}</button></span></label>{error&&<div className="errorBox" role="alert">{error}</div>}<button disabled={busy} aria-busy={busy} className="btn primary full authSubmit">{busy?<><span className="spinner" aria-hidden="true"/> Please wait</>:<>{signup?'Create account':'Sign in'} <ChevronRight size={17}/></>}</button></form><div className="authSwitch">{signup?'Already registered?':'New to CloudReady?'} <Link to={signup?'/signin':'/signup'} state={loc.state}>{signup?'Sign in':'Create an account'}</Link></div><p className="authLegal"><ShieldCheck size={15}/><span>Your account is used only for learning progress and study preferences.</span></p></div></div></section>}
function Quiz(){const[i,setI]=useState(0),[answers,setAnswers]=useState({}),[submitted,setSubmitted]=useState(false),[saved,setSaved]=useState(false);const q=questions[i],score=questions.filter((x,n)=>answers[n]===x.answer).length;async function finish(){setSubmitted(true);const record={score,total:questions.length,date:new Date().toISOString()};const history=JSON.parse(localStorage.getItem('cr_history')||'[]');localStorage.setItem('cr_history',JSON.stringify([record,...history].slice(0,50)));const token=localStorage.getItem('cr_token');if(token){try{await fetch(`${API}/progress`,{method:'POST',headers:{'Content-Type':'application/json',Authorization:'Bearer '+token},body:JSON.stringify({score,total:questions.length,topic:'Mixed practice'})});setSaved(true)}catch{}}}function choose(n){if(!submitted&&answers[i]===undefined)setAnswers({...answers,[i]:n})}return <><PageHero eyebrow="PRACTICE QUIZ" title={<>Build confidence through<br/><em>active recall.</em></>} desc="Answer original questions and read the explanation after each response."/><section className="quizWrap wrap"><div className="quizMeta"><span>Question {i+1} of {questions.length}</span><span>{q.topic}</span></div><div className="progressTrack" role="progressbar" aria-label="Quiz progress" aria-valuemin={1} aria-valuemax={questions.length} aria-valuenow={i+1}><i style={{transform:`scaleX(${(i+1)/questions.length})`}}/></div>{submitted?<div className="resultCard"><span className="largeIcon"><Target/></span><h2>Your practice result</h2><div className="resultScore"><CountUp to={score}/> / {questions.length}</div><p>You answered {Math.round(score/questions.length*100)}% correctly. Review the explanations and try again to strengthen recall.{saved?' Your result was synced to your account.':''}</p><button className="btn primary" onClick={()=>{setI(0);setAnswers({});setSubmitted(false)}}>Try again</button></div>:<div className="quizCard" key={i}><div className="eyebrow">{q.topic.toUpperCase()}</div><h2>{q.q}</h2><div className="optionList" role="group" aria-label="Answer options">{q.opts.map((opt,n)=>{const locked=answers[i]!==undefined,isRight=locked&&n===q.answer,isWrong=locked&&answers[i]===n&&n!==q.answer;return <button type="button" key={opt} aria-disabled={locked} className={'option'+(answers[i]===n?' selected':'')+(isRight?' correct':'')+(isWrong?' wrong':'')} onClick={()=>choose(n)}><span>{String.fromCharCode(65+n)}</span>{opt}{isRight&&<CheckCircle2 className="optionMark" size={18} aria-label="Correct answer"/>}{isWrong&&<X className="optionMark" size={18} aria-label="Your answer, incorrect"/>}</button>;})}</div>{answers[i]!==undefined&&<div role="status" className={'answerExplain '+(answers[i]===q.answer?'correct':'incorrect')}><b>{answers[i]===q.answer?'Correct answer':'Review this concept'}</b><p>{q.why}</p></div>}<div className="quizControls"><button className="btn secondary" disabled={i===0} onClick={()=>setI(i-1)}>Previous</button>{i<questions.length-1?<button className="btn primary" disabled={answers[i]===undefined} onClick={()=>setI(i+1)}>Next question <ChevronRight size={16}/></button>:<button className="btn primary" disabled={answers[i]===undefined} onClick={finish}>View results</button>}</div></div>}</section></>}
function Flashcards(){const[at,setAt]=useState(0),[show,setShow]=useState(false),[known,setKnown]=useState([]);const cards=[['What is cloud computing?','The delivery of computing services over a network, usually with usage based pricing.'],['What is elasticity?','The ability to adjust resources as demand changes.'],['What is high availability?','Designing a service to remain accessible with minimal interruption.'],['What is least privilege?','Giving identities only the permissions needed to complete their tasks.'],['What is a hybrid cloud?','An environment that combines private infrastructure with public cloud services.'],['What does Azure Policy help with?','Assessing and enforcing organizational rules for cloud resources.']];function next(){setAt((at+1)%cards.length);setShow(false)}useEffect(()=>{const onKey=e=>{if(e.target.closest&&e.target.closest('input,textarea,select'))return;if(e.key==='ArrowRight'){setAt(a=>(a+1)%cards.length);setShow(false);}if(e.key==='ArrowLeft'){setAt(a=>(a-1+cards.length)%cards.length);setShow(false);}};window.addEventListener('keydown',onKey);return()=>window.removeEventListener('keydown',onKey);},[cards.length]);return <><PageHero eyebrow="FLASHCARDS" title={<>Strengthen recall,<br/><em>one card at a time.</em></>} desc="Reveal the answer, decide how well you know it, and revisit difficult concepts."/><section className="flashWrap wrap"><div className="flashProgress"><span>Card {at+1} of {cards.length}</span><span>{known.length} marked as known</span></div><button type="button" className={'flashCard '+(show?'revealed':'')} onClick={()=>setShow(!show)} aria-live="polite"><span className="flashFace" key={at+'-'+show}><span className="flashLabel">{show?'ANSWER':'QUESTION'}</span><span className="flashText">{cards[at][show?1:0]}</span><small>Press to {show?'see question':'reveal answer'}. Arrow keys change card.</small></span></button><div className="flashActions"><button className="btn secondary" onClick={()=>{setKnown(known.filter(n=>n!==at));next()}}>Review again</button><button className="btn primary" onClick={()=>{setKnown([...new Set([...known,at])]);next()}}><CheckCircle2 size={17}/> I know this</button></div><div className="flashDots">{cards.map((c,n)=><button type="button" aria-label={'Go to card '+(n+1)} aria-current={at===n?'true':undefined} className={at===n?'active':''} key={c[0]} onClick={()=>{setAt(n);setShow(false)}}/>)}</div></section></>}
function Planner(){const[date,setDate]=useState('2026-11-20'),[minutes,setMinutes]=useState('45'),[saved,setSaved]=useState(false),[message,setMessage]=useState('');return <><PageHero eyebrow="STUDY PLANNER" title={<>Make room for<br/><em>steady progress.</em></>} desc="Create a realistic plan based on your target date and the time you can study."/><section className="plannerGrid wrap"><form className="formCard" onSubmit={async e=>{e.preventDefault();setSaved(true);setMessage('Saved on this device.');localStorage.setItem('cr_plan',JSON.stringify({date,minutes}));const token=localStorage.getItem('cr_token');if(token){try{const r=await fetch(`${API}/plan`,{method:'PUT',headers:{'Content-Type':'application/json',Authorization:'Bearer '+token},body:JSON.stringify({targetDate:date,dailyMinutes:Number(minutes)})});if(!r.ok)throw new Error();setMessage('Saved on this device and synced to your account.')}catch{setMessage('Saved on this device. Account sync is temporarily unavailable.')}}}}><h2>Your study preferences</h2><label>Target exam date<input type="date" value={date} onChange={e=>{setDate(e.target.value);setSaved(false)}} required/></label><label>Available study time<select value={minutes} onChange={e=>{setMinutes(e.target.value);setSaved(false)}}><option value="20">20 minutes each day</option><option value="45">45 minutes each day</option><option value="60">1 hour each day</option><option value="90">90 minutes each day</option></select></label><button className="btn primary full">Build my study plan <ChevronRight size={17}/></button>{saved&&<div className="successInline"><CheckCircle2 size={17}/> {message}</div>}</form><div className="planPreview"><span className="largeIcon"><CalendarDays/></span><h2>Your weekly rhythm</h2><p>Keep sessions focused and leave time to revisit concepts that need more attention.</p>{[['Monday','Cloud concepts'],['Tuesday','Architecture and services'],['Wednesday','Security and identity'],['Thursday','Management and governance'],['Friday','Mixed practice questions'],['Saturday','Review difficult concepts'],['Sunday','Rest or light flashcards']].map((r,i)=><div className="planRow" key={r[0]} style={{'--i':i}}><span>{r[0].slice(0,3)}</span><div><b>{r[1]}</b><small>{minutes} minutes</small></div><CheckCircle2 size={17}/></div>)}</div></section></>}
function Progress(){const[history,setHistory]=useState(()=>JSON.parse(localStorage.getItem('cr_history')||'[]'));return <><PageHero eyebrow="PROGRESS REPORT" title={<>Notice how far<br/><em>you have come.</em></>} desc="Review your practice activity and use the results to decide what to study next."/><section className="wrap progressPage"><div className="progressCards"><Stat icon={<Target/>} number={history.length?history.length:'0'} label="Completed practice sets"/><Stat icon={<ChartNoAxesColumnIncreasing/>} number={history.length?Math.round(history.reduce((a,x)=>a+x.score,0)/history.reduce((a,x)=>a+x.total,0)*100)+'%':'Not yet'} label="Recorded accuracy"/><Stat icon={<BookMarked/>} number="6" label="Flashcards in this set"/></div><div className="reportCard"><div className="sectionHead"><div><h2>Topic study guide</h2><p>Suggested starting points for your next session.</p></div><button className="btn secondary" onClick={()=>window.print()}>Print report</button></div>{topics.map(([name,val])=><div className="masteryRow" key={name}><div><span>{name}</span><b>{val}% sample mastery</b></div><span className="bar"><i style={{width:val+'%'}}/></span></div>)}<p className="finePrint">Sample topic values are illustrative until you complete and save practice sessions. This report is a study aid and is not an official readiness score.</p></div><div className="cta smallCta"><div><h2>Ready to practise?</h2><p>Complete a quiz to start building a personal learning history.</p></div><Link className="btn primary" to="/quiz">Start quiz</Link></div></section></>}
function Assistant(){
 const loc=useLocation(),[mode,setMode]=useState('summary'),[topic,setTopic]=useState(loc.state?.topic||''),[text,setText]=useState(''),[result,setResult]=useState(''),[busy,setBusy]=useState(false),[exporting,setExporting]=useState(false),[error,setError]=useState(''),[exportError,setExportError]=useState('');
 async function run(e){
  e.preventDefault();setBusy(true);setError('');setExportError('');setResult('');
  try{const token=localStorage.getItem('cr_token');const res=await fetch(`${API}/study/${mode}`,{method:'POST',headers:{'Content-Type':'application/json',...(token?{Authorization:'Bearer '+token}:{})},body:JSON.stringify({topic,content:text})});const data=await res.json();if(!res.ok)throw new Error(data.error||'Unable to complete this request');setResult(data.result);}
  catch(err){setError(err instanceof TypeError?'Could not reach the API server. Check that it is running and try again.':err instanceof Error?err.message:'Unable to complete this request. Please try again.');}
  finally{setBusy(false);}
 }
 async function exportResult(format){
  setExporting(true);setExportError('');
  const heading=mode==='summary'?'Study summary':'Research notes',label=topic.trim()?`${heading} - ${topic.trim()}`:heading,filename=label.toLowerCase().replace(/[^a-z0-9]+/g,'-').replace(/^-|-$/g,'').slice(0,80)||'study-result',date=new Date().toLocaleDateString();
  try{
   if(format==='pdf'){
    const{jsPDF}=await import('jspdf');
    const pdf=new jsPDF({unit:'mm',format:'a4'}),margin=18,lineWidth=174;let y=20;
    const write=(value,size=11,style='normal')=>{pdf.setFont('helvetica',style);pdf.setFontSize(size);const lines=pdf.splitTextToSize(value, lineWidth);for(const line of lines){if(y>279){pdf.addPage();y=18;}pdf.text(line,margin,y);y+=size*0.48+2;}};
    const pdfText=value=>value.normalize('NFD').replace(/[\u0300-\u036f]/g,'').replace(/[“”]/g,'"').replace(/[‘’]/g,"'").replace(/[–—]/g,'-').replace(/[^\x20-\x7e]/g,'');
    write(pdfText(label),18,'bold');write(`Created ${date}`,10);y+=3;
    result.split(/\r?\n/).forEach(raw=>{if(!raw.trim()){y+=3;return;}const isHeading=/^#{1,6}\s+/.test(raw),line=pdfText(raw.replace(/^#{1,6}\s+/,'').replace(/^\s*[-*]\s+/,'- ').replace(/\*\*(.*?)\*\*/g,'$1'));write(line,isHeading?13:11,isHeading?'bold':'normal');});
    pdf.save(`${filename}.pdf`);
   }else{
    const{Document,HeadingLevel,Packer,Paragraph}=await import('docx');
    const paragraphs=result.split(/\r?\n/).map(raw=>{const title=raw.match(/^#{1,6}\s+(.+)$/),bullet=raw.match(/^\s*[-*]\s+(.+)$/);if(title)return new Paragraph({text:title[1],heading:HeadingLevel.HEADING_2});if(bullet)return new Paragraph({text:bullet[1],bullet:{indent:360}});return new Paragraph({text:raw.replace(/\*\*(.*?)\*\*/g,'$1')});});
    const wordDocument=new Document({sections:[{children:[new Paragraph({text:label,heading:HeadingLevel.TITLE}),new Paragraph({text:`Created ${date}`}),...paragraphs]}]});
    const blob=await Packer.toBlob(wordDocument),url=URL.createObjectURL(blob),link=document.createElement('a');link.href=url;link.download=`${filename}.docx`;document.body.appendChild(link);link.click();link.remove();setTimeout(()=>URL.revokeObjectURL(url),1000);
   }
  }catch(err){setExportError(err instanceof Error?err.message:'Could not create the download. Please try again.');}
  finally{setExporting(false);}
 }
 const setStudyMode=next=>{setMode(next);setResult('');setError('');setExportError('');},resultHeading=mode==='summary'?'Your summary':'Research notes';
 return <><PageHero eyebrow="STUDY ASSISTANT" title={<>Research and summarize<br/><em>without losing your focus.</em></>} desc="Use the in platform study assistant to summarize your notes or explore a cloud topic. Results depend on the configured AI service and should be checked against trusted learning materials."/><section className="assistantGrid wrap"><div className="assistantIntro"><span className="largeIcon"><Sparkles/></span><h2>Your study workspace</h2><p>Choose a task, provide notes or a topic, and receive a structured response in this page. Keep personal or confidential information out of prompts.</p><div className="assistantModes"><button type="button" aria-pressed={mode==='summary'} className={mode==='summary'?'mode active':'mode'} onClick={()=>setStudyMode('summary')}><FileText/> Summarize notes</button><button type="button" aria-pressed={mode==='research'} className={mode==='research'?'mode active':'mode'} onClick={()=>setStudyMode('research')}><Search/> Research a topic</button></div></div><form className="formCard assistantForm" onSubmit={run}><div className="assistantFormHead"><span className="toolIcon"><Brain/></span><div><h2>{mode==='summary'?'Summarize learning notes':'Research a cloud topic'}</h2><p>{mode==='summary'?'Turn long notes into a clear revision summary.':'Get a beginner friendly overview and important questions.'}</p></div></div>{mode==='research'&&<label>Topic to research<input value={topic} onChange={e=>setTopic(e.target.value)} required placeholder="For example, cloud availability zones"/></label>}<label>{mode==='summary'?'Paste your notes':'What do you want to understand?'}<textarea rows="7" value={text} onChange={e=>setText(e.target.value)} required placeholder={mode==='summary'?'Paste your own notes or study material here...':'Add context or a specific question to guide the research...'}/></label><button className="btn primary full" disabled={busy}>{busy?<><span className="spinner" aria-hidden="true"/> Working on your request</>:<>{mode==='summary'?'Create summary':'Research topic'} <Sparkles size={17}/></>}</button>{error&&<div className="errorBox" role="alert">{error}</div>}{result&&<div className="aiResult"><div className="resultHead"><h3>{resultHeading}</h3><button type="button" className="iconBtn" onClick={()=>navigator.clipboard?.writeText(result)} title="Copy result" aria-label="Copy result"><BookMarked size={17}/></button></div><div className="resultText">{result}</div><div className="resultDownloads" aria-label="Download result"><button type="button" className="btn secondary small" disabled={exporting} onClick={()=>exportResult('pdf')}><Download size={16}/> Download PDF</button><button type="button" className="btn secondary small" disabled={exporting} onClick={()=>exportResult('word')}><Download size={16}/> Download Word (.docx)</button></div>{exportError&&<div className="errorBox" role="alert">{exportError}</div>}<p className="finePrint">Review facts and follow any cited sources before relying on this material.</p></div>}</form></section></>}
